style.css:
@-moz-document domain("roblox.com") {
/* Force background behind everything */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;

        background: url("https://giffiles.alphacoders.com/156/15638.gif") center center / cover no-repeat;

        z-index: -9999;
    }
}
